# F01/F02. HTML autónomos desde datos congelados; no modifica los insumos.
# Rscript --vanilla plots/capitulo-01/generar_fisico_web.R
file_arg <- grep("^--file=", commandArgs(trailingOnly = FALSE), value = TRUE)
if (length(file_arg) != 1L) stop("Ejecute este generador con Rscript.")
script_file <- normalizePath(sub("^--file=", "", file_arg), winslash = "/", mustWork = TRUE)
here <- dirname(script_file)
root <- normalizePath(file.path(here, "..", ".."), winslash = "/", mustWork = TRUE)
extra_libs <- Sys.getenv("PAPIME_R_LIBRARY", "")
if (nzchar(extra_libs)) .libPaths(c(strsplit(extra_libs, .Platform$path.sep, fixed = TRUE)[[1]], .libPaths()))
if (.Platform$OS.type == "windows") invisible(suppressWarnings(Sys.setlocale("LC_CTYPE", "English_United States.utf8")))
for (p in c("sf", "terra", "jsonlite", "base64enc"))
  if (!requireNamespace(p, quietly = TRUE)) stop("Falta el paquete R: ", p)
src <- file.path(root, "datos", "capitulo-01")
global <- file.path(root, "datos", "globales")
dst <- here
states<-sf::st_read(file.path(src,'F01-estados.gpkg'),quiet=TRUE)
prov<-sf::st_read(file.path(src,'F01-provincias.gpkg'),quiet=TRUE)
bb<-as.numeric(sf::st_bbox(states));names(bb)<-c('xmin','ymin','xmax','ymax')
W<-1000;H<-round(W*(bb['ymax']-bb['ymin'])/(bb['xmax']-bb['xmin']))
xy<-function(m)cbind((m[,1]-bb['xmin'])/(bb['xmax']-bb['xmin'])*W,(bb['ymax']-m[,2])/(bb['ymax']-bb['ymin'])*H)
mpath<-function(m,close=FALSE){p<-xy(as.matrix(m)[,1:2,drop=FALSE]);if(nrow(p)<2)return('');paste0('M',paste(apply(round(p,1),1,paste,collapse=','),collapse=' '),if(close)'Z'else'')}
gpath<-function(g){
 type<-class(g)[class(g)%in%c('POLYGON','MULTIPOLYGON','LINESTRING','MULTILINESTRING')][1]
 if(type=='POLYGON')return(paste(vapply(g,mpath,'',close=TRUE),collapse=''))
 if(type=='MULTIPOLYGON')return(paste(vapply(g,function(p)paste(vapply(p,mpath,'',close=TRUE),collapse=''),''),collapse=''))
 if(type=='LINESTRING')return(mpath(g))
 if(type=='MULTILINESTRING')return(paste(vapply(g,mpath,''),collapse=''))
 ''
}
paths<-function(obj,tol=1000)vapply(sf::st_geometry(sf::st_simplify(obj,dTolerance=tol,preserveTopology=TRUE)),gpath,'')
state_data<-jsonlite::fromJSON(file.path(global,'estados-web.json'))$estados
stopifnot(nrow(state_data)==32L, setequal(state_data$cve_ent,as.character(states$CVE_ENT)))

labs_e<-c('Menos de 0','0 a <200','200 a <500','500 a <1 000','1 000 a <2 000','2 000 a <3 000','3 000 o más')
labs_c<-c('Cálido húmedo','Cálido subhúmedo','Semicálido húmedo','Semicálido subhúmedo','Templado húmedo','Templado subhúmedo','Semifrío subhúmedo','Secos y semisecos','Frío','Agua')
labs_s<-c('Piedras (R)','Gravas y guijarros (r)','Sin fase registrada (N)','Agua','Localidad (sin clasificación)','Arrecife (no aplica)','Dato inconsistente')
col_e<-c('#17324D','#285944','#52785C','#82936A','#B0AD8C','#DACAB5','#F1EFEA')
col_c<-c('#073C2A','#879D7F','#347F7A','#8EC4BC','#5B7E9B','#B4D5DB','#8B85AA','#EEE8BE','#35333F','#E6F3F8')
col_s<-c('#65542D','#A18C59','#E7E5E0','#C9E2EC','#A8A9AA','#7FBAB5','#A65C87')
readmap<-function(name,type){
 r<-terra::rast(file.path(src,name)); m<-terra::as.matrix(r,wide=TRUE);m[abs(m)>1e20]<-NA
 if(type=='e')m<-matrix(as.integer(cut(m,breaks=c(-Inf,0,200,500,1000,2000,3000,Inf),right=FALSE)),nrow=nrow(m))
 colors<-switch(type,e=col_e,c=col_c,s=col_s)
 pixels<-matrix('#FFFFFF00',nrow(m),ncol(m));pixels[!is.na(m)]<-colors[m[!is.na(m)]]
 list(m=m,pixels=pixels)
}
inline_raster<-function(layer,id,group=NULL){
 f<-tempfile(paste0('papime-fisico-',id,'-'),fileext='.png');m<-layer$pixels
 if(!is.null(group))m[is.na(layer$m)|layer$m!=group]<-'#FFFFFF00'
 png(f,width=ncol(m),height=nrow(m),bg='transparent',type='cairo');grid::grid.newpage();grid::grid.raster(m,interpolate=FALSE);dev.off()
 uri<-base64enc::dataURI(file=f,mime='image/png');unlink(f);uri
}
escape<-function(s){s<-gsub('&','&amp;',s,fixed=TRUE);s<-gsub('<','&lt;',s,fixed=TRUE);gsub('"','&quot;',s,fixed=TRUE)}
json<-function(x)gsub('<','\\u003c',jsonlite::toJSON(x,auto_unbox=TRUE,digits=15,na='null',dataframe='rows'),fixed=TRUE)
css <- paste(readLines(file.path(root, "estilos", "widgets", "fisico.css"), encoding = "UTF-8", warn = FALSE), collapse = "\n")
css <- paste0("\n", css, "\n")
helpers<-r"---(
const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c])), plain=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(), num=new Intl.NumberFormat('es-MX',{maximumFractionDigits:4});
function csvDownload(name,fields,rows){const cell=v=>'"'+String(v??'').replace(/"/g,'""')+'"',csv=[fields.map(cell).join(','),...rows.map(r=>fields.map(k=>cell(r[k])).join(','))].join('\r\n')+'\r\n',u=URL.createObjectURL(new Blob(['\uFEFF',csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),30000)}
function activate(el,fn){el.addEventListener('click',fn);el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();fn(e)}})}
function toggle(set,id){set.has(id)?set.delete(id):set.add(id)}
function captureFocus(){const a=document.activeElement;if(!a)return null;if(a.dataset.state)return ['state',a.dataset.state];if(a.dataset.city)return ['city',a.dataset.city];if(a.dataset.row)return ['row',a.dataset.row];if(a.closest('#state-options')&&a.value)return ['state-input',a.value];if(a.closest('#city-options')&&a.value)return ['city-input',a.value];if(a.closest('#category-options')&&a.value)return ['category-input',a.value];return null}
function restoreFocus(t){if(!t)return;const selectors={state:'[data-state="'+t[1]+'"]',city:'[data-city="'+t[1]+'"]',row:'[data-row="'+t[1]+'"]','state-input':'#state-options input[value="'+t[1]+'"]','city-input':'#city-options input[value="'+t[1]+'"]','category-input':'#category-options input[value="'+t[1]+'"]'};document.querySelector(selectors[t[0]])?.focus({preventScroll:true})}
function chips(el,items,remove){el.replaceChildren();for(const item of items){const b=document.createElement('button');b.type='button';b.className='chip';b.textContent=item.name+' ×';b.setAttribute('aria-label','Quitar '+item.name);b.addEventListener('click',()=>remove(item.id));el.append(b)}}
function stateOptions(query,set,change){const q=plain(query),el=$('state-options');el.replaceChildren();for(const s of D.estados.filter(s=>plain(s.nombre).includes(q))){const label=document.createElement('label');label.className='option';const c=document.createElement('input');c.type='checkbox';c.value=s.cve_ent;c.checked=set.has(s.cve_ent);c.addEventListener('change',()=>change(s.cve_ent));label.append(c,document.createTextNode(s.nombre));el.append(label)}if(!el.children.length)el.innerHTML='<p class="empty">No se encontraron entidades.</p>'}
function stateMap(set,change){$('states').innerHTML=D.estados.map(s=>'<path class="state'+(set.has(s.cve_ent)?' selected':'')+'" data-state="'+s.cve_ent+'" d="'+s.d+'" fill-rule="evenodd" role="button" tabindex="0" aria-label="'+esc(s.nombre)+'" aria-pressed="'+set.has(s.cve_ent)+'"><title>'+esc(s.nombre)+'</title></path>').join('');document.querySelectorAll('[data-state]').forEach(p=>activate(p,()=>change(p.dataset.state)))}
const nationalBox=$('map').getAttribute('viewBox'),zoomTools=document.createElement('div');zoomTools.className='map-tools';zoomTools.innerHTML='<button id="zoom-selection" disabled>Acercar selección</button><button id="zoom-national">Vista nacional</button>';$('map').before(zoomTools);
function nationalView(){$('map').setAttribute('viewBox',nationalBox)}
$('zoom-national').addEventListener('click',nationalView);$('reset').addEventListener('click',nationalView);
$('zoom-selection').addEventListener('click',()=>{const selected=[...document.querySelectorAll('#states .selected,#cities .selected')];if(!selected.length)return;const boxes=selected.map(el=>el.getBBox()),x=Math.min(...boxes.map(b=>b.x)),y=Math.min(...boxes.map(b=>b.y)),right=Math.max(...boxes.map(b=>b.x+b.width)),bottom=Math.max(...boxes.map(b=>b.y+b.height)),pad=Math.max(12,Math.max(right-x,bottom-y)*.12);$('map').setAttribute('viewBox',[x-pad,y-pad,right-x+2*pad,bottom-y+2*pad].join(' '))});
function publishHeight(){$('zoom-selection').disabled=!document.querySelector('#states .selected,#cities .selected');if(parent!==window)parent.postMessage({type:'papime:resize',height:Math.ceil(document.body.getBoundingClientRect().height)+32},'*')}
new ResizeObserver(publishHeight).observe(document.body);window.addEventListener('load',publishHeight);
)---"
page<-function(name,title,body,dat,js){
 html<-paste0('<!doctype html><html lang="es-MX"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>',title,'</title><style>',css,'</style></head><body><h1>',title,'</h1>',body,'<script id="figure-data" type="application/json">',json(dat),'</script><script>"use strict";const D=JSON.parse(document.getElementById("figure-data").textContent);',helpers,js,'</script></body></html>')
 writeLines(html,file.path(dst,name),useBytes=TRUE)
}
state_selector<-'<section class="selector"><h2>Comparar entidades</h2><label for="state-search">Buscar entidad</label><input id="state-search" type="search" placeholder="Nombre de la entidad" autocomplete="off"><div id="state-options" class="options" aria-label="Entidades seleccionables"></div></section>'

# F01: las filas y exportaciones conservan la unidad localidad y el corte 2020.
local<-read.csv(file.path(src,'F01-localidades-2020.csv'),colClasses='character',check.names=FALSE,encoding='UTF-8')
local_sf<-local;local_sf$longitud<-as.numeric(local_sf$longitud);local_sf$latitud<-as.numeric(local_sf$latitud)
loc<-sf::st_transform(sf::st_as_sf(local_sf,coords=c('longitud','latitud'),crs=6365,remove=FALSE),sf::st_crs(states))
coords<-xy(sf::st_coordinates(loc));local$cx<-round(coords[,1],1);local$cy<-round(coords[,2],1)
roads<-sf::st_read(file.path(src,'F01-carreteras-federales.gpkg'),quiet=TRUE)
elev<-readmap('F01-elevacion-1800m.tif','e')
f01body<-paste0('<p class="muted">INEGI · localidades del Censo 2020 · carreteras 2025 · elevación CEM 3.0, archivo 20170619 · provincias 2001 · límites 2020.</p><p>La selección de entidades reúne las localidades censales representadas en ellas. Puede comparar asentamientos concretos, seguir su posición en el relieve y consultar sus cifras junto al mapa.</p><div class="toolbar"><button id="reset">Restablecer vista</button><button id="download" class="primary">Descargar localidades mostradas CSV</button></div><div class="selectors">',state_selector,'<section class="selector"><h2>Comparar localidades</h2><label for="city-search">Buscar localidad o entidad</label><input id="city-search" type="search" placeholder="Nombre de la localidad" autocomplete="off"><div id="city-options" class="options" aria-label="Localidades seleccionables"></div></section></div><div id="selection-chips" class="chips" aria-label="Selección activa"></div><section id="detail" class="detail" aria-live="polite"></section><fieldset class="layer-controls"><legend>Vista y capas</legend><label><input type="radio" name="view" value="elevacion" checked>Relieve</label><label><input type="radio" name="view" value="poblamiento">Poblamiento y conexiones</label><label><input id="provinces-toggle" type="checkbox" checked>Provincias</label><label><input id="roads-toggle" type="checkbox" checked>Carreteras</label><label><input id="cities-toggle" type="checkbox" checked>Localidades</label></fieldset><p class="keyboard-hint">En el mapa, clic o toque añade o quita una entidad o localidad. Con teclado, Tab recorre los elementos y Enter o Espacio confirma. Las listas ofrecen la misma selección.</p><svg id="map" class="map" viewBox="0 0 ',W,' ',H,'" role="group" aria-label="Mapa seleccionable de relieve, entidades y localidades"><image id="elevation" href="',inline_raster(elev,'elevacion'),'" width="',W,'" height="',H,'"/><path id="provinces" d="',paste(paths(prov),collapse=''),'" fill="none" stroke="#59635b" stroke-width=".6" pointer-events="none"/><path id="roads" class="hidden" d="',paste(paths(roads),collapse=''),'" fill="none" stroke="#78959f" stroke-width=".9" pointer-events="none"/><g id="states"></g><g id="cities" class="hidden"></g></svg><ul id="elevation-legend" class="legend">',paste0('<li><span class="swatch" style="background:',col_e,'"></span>',escape(labs_e),'</li>',collapse=''),'</ul><p id="population-legend" class="muted hidden">El área de los círculos representa la población. El contorno naranja identifica la selección.</p><div class="table-wrap"><table id="data-table"><caption id="table-caption"></caption><thead><tr><th scope="col">Localidad</th><th scope="col">Entidad</th><th scope="col" class="number">Población 2020</th><th scope="col" class="number">Altitud censal (m)</th></tr></thead><tbody id="table-body"></tbody></table></div><p class="source">Las 145 localidades de al menos 100 000 habitantes reúnen 61 026 805 personas, 48.43% de la población nacional censal de 2020. Los totales mostrados reúnen sólo estas localidades, con agregados municipales y estatales excluidos. Una ciudad funcional puede reunir varias localidades. La red representa carreteras federales habilitadas y en operación; el acceso a servicios requiere además información de viajes y destinos.</p><details><summary>Fuentes, selección y escala</summary><p class="muted">INEGI, CEM 3.0, provincias fisiográficas 2001, ITER 2020 y RNC 2025. Elevación agregada y proyectada a 1.8 km; contornos y líneas simplificados sólo para dibujo nacional. La generalización puede omitir islas pequeñas. Filtros viales: TIPO_VIAL=Carretera, ADMINISTRA=Federal, ESTATUS=Habilitado y CONDICION=En operación. Consulta documental 5 de noviembre de 2026.</p></details>')
f01js<-r"---(
const selectedStates=new Set(),selectedCities=new Set();let view='elevacion',lastCity=null;
const candidates=()=>D.localidades.filter(r=>(!selectedStates.size||selectedStates.has(r.cve_ent))&&plain(r.localidad+' '+r.entidad).includes(plain($('city-search').value)));
const shown=()=>candidates().filter(r=>!selectedCities.size||selectedCities.has(r.cveloc));
function changeState(id){toggle(selectedStates,id);selectedCities.clear();lastCity=null;render()}
function changeCity(id){toggle(selectedCities,id);lastCity=selectedCities.has(id)?id:null;view='poblamiento';document.querySelector('input[name=view][value=poblamiento]').checked=true;render()}
function cityOptions(){const el=$('city-options');el.replaceChildren();for(const r of candidates()){const l=document.createElement('label');l.className='option';const c=document.createElement('input');c.type='checkbox';c.value=r.cveloc;c.checked=selectedCities.has(r.cveloc);c.addEventListener('change',()=>changeCity(r.cveloc));l.append(c,document.createTextNode(r.localidad+' · '+r.entidad));el.append(l)}if(!el.children.length)el.innerHTML='<p class="empty">No hay localidades con esta búsqueda.</p>'}
function render(){const focus=captureFocus(),rows=shown(),visible=new Set(rows.map(r=>r.cveloc)),sum=rows.reduce((a,r)=>a+Number(r.poblacion),0);stateOptions($('state-search').value,selectedStates,changeState);cityOptions();stateMap(selectedStates,changeState);chips($('selection-chips'),[...D.estados.filter(s=>selectedStates.has(s.cve_ent)).map(s=>({id:'s'+s.cve_ent,name:s.nombre})),...D.localidades.filter(r=>selectedCities.has(r.cveloc)).map(r=>({id:'c'+r.cveloc,name:r.localidad}))],id=>id[0]==='s'?changeState(id.slice(1)):changeCity(id.slice(1)));
$('cities').innerHTML=D.localidades.map(r=>'<g class="city'+(selectedCities.has(r.cveloc)?' selected':'')+(visible.has(r.cveloc)?'':' dim')+'" data-city="'+r.cveloc+'" role="button" tabindex="'+(visible.has(r.cveloc)?'0':'-1')+'" aria-pressed="'+selectedCities.has(r.cveloc)+'" aria-label="'+esc(r.localidad+', '+r.entidad+', '+num.format(Number(r.poblacion))+' habitantes')+'"><circle cx="'+r.cx+'" cy="'+r.cy+'" r="14" fill="transparent"/><circle class="symbol" cx="'+r.cx+'" cy="'+r.cy+'" r="'+Math.sqrt(Number(r.poblacion)/100000)*2.7+'"/><title>'+esc(r.localidad+' · '+r.entidad)+'</title></g>').join('');document.querySelectorAll('[data-city]').forEach(g=>activate(g,()=>changeCity(g.dataset.city)));
$('elevation').classList.toggle('hidden',view!=='elevacion');$('elevation-legend').classList.toggle('hidden',view!=='elevacion');$('population-legend').classList.toggle('hidden',view!=='poblamiento');$('provinces').classList.toggle('hidden',view!=='elevacion'||!$('provinces-toggle').checked);$('roads').classList.toggle('hidden',view!=='poblamiento'||!$('roads-toggle').checked);$('cities').classList.toggle('hidden',view!=='poblamiento'||!$('cities-toggle').checked);
const stateNames=D.estados.filter(s=>selectedStates.has(s.cve_ent)).map(s=>s.nombre);$('detail').innerHTML='<p class="status">'+rows.length+' localidades mostradas · '+num.format(sum)+' habitantes en la selección</p><p>'+(stateNames.length?'Entidades: '+esc(stateNames.join(', '))+'.':'Vista nacional de las localidades seleccionadas por el umbral censal.')+'</p>'+(lastCity?(()=>{const r=D.localidades.find(r=>r.cveloc===lastCity);return '<p><strong>'+esc(r.localidad)+'</strong> · '+esc(r.entidad)+' · '+num.format(Number(r.poblacion))+' habitantes · altitud censal '+num.format(Number(r.altitud_censal_m))+' m.</p>'})():'')+'<p class="muted">Corte 2020. La población seleccionada es la suma de las filas de la tabla.</p>';
$('table-caption').textContent='Localidades mostradas: '+rows.length+' de '+D.localidades.length;$('table-body').innerHTML=rows.map(r=>'<tr class="'+(selectedCities.has(r.cveloc)?'selected':'')+'"><td><button data-row="'+r.cveloc+'" aria-pressed="'+selectedCities.has(r.cveloc)+'">'+esc(r.localidad)+'</button></td><td>'+esc(r.entidad)+'</td><td class="number">'+num.format(Number(r.poblacion))+'</td><td class="number">'+num.format(Number(r.altitud_censal_m))+'</td></tr>').join('')||'<tr><td colspan="4" class="empty">La selección y la búsqueda actuales no reúnen localidades. Restablecer recupera la vista nacional.</td></tr>';document.querySelectorAll('[data-row]').forEach(b=>b.addEventListener('click',()=>changeCity(b.dataset.row)));$('download').disabled=!rows.length;restoreFocus(focus);publishHeight()}
$('state-search').addEventListener('input',()=>stateOptions($('state-search').value,selectedStates,changeState));$('city-search').addEventListener('input',render);document.querySelectorAll('input[name=view]').forEach(r=>r.addEventListener('change',()=>{view=r.value;render()}));for(const id of ['provinces-toggle','roads-toggle','cities-toggle'])$(id).addEventListener('change',render);
$('reset').addEventListener('click',()=>{selectedStates.clear();selectedCities.clear();lastCity=null;$('state-search').value='';$('city-search').value='';view='elevacion';document.querySelector('input[name=view][value=elevacion]').checked=true;for(const id of ['provinces-toggle','roads-toggle','cities-toggle'])$(id).checked=true;render()});$('download').addEventListener('click',()=>csvDownload('F01-localidades-mostradas-2020.csv',D.campos,shown()));window.figureState=()=>({estados:[...selectedStates],localidades:[...selectedCities],filas:shown(),vista:view});render();
)---"
page('F01-relieve-localizacion.html','Relieve, poblamiento y conexiones de México',f01body,list(estados=state_data,localidades=local,campos=names(local)[1:8]),f01js)
cat('F01: explorador HTML generado.\n')

# F02. Los contornos estatales son contexto; la clasificación mantiene su escala nacional.
climate<-readmap('F02-climas-1800m.tif','c');soil<-readmap('F02-suelos-1800m.tif','s')
climate_rows<-read.csv(file.path(src,'F02-correspondencia-climas.csv'),colClasses='character',check.names=FALSE,encoding='UTF-8',na.strings=character())
soil_rows<-read.csv(file.path(src,'F02-correspondencia-suelos.csv'),colClasses='character',check.names=FALSE,encoding='UTF-8',na.strings=character())
layer_data<-function(layer,labels,colors,rows,fields){
 ids<-seq_along(labels)
 m<-layer$m;m[is.na(m)]<-0
 runs<-rle(as.integer(as.vector(t(m))))
 stopifnot(identical(inverse.rle(runs),as.integer(as.vector(t(m)))))
 list(categorias=data.frame(id=ids,nombre=labels,color=colors),filas=rows,campos=fields,columnas=ncol(m),renglones=nrow(m),runs=list(lengths=runs$lengths,values=runs$values))
}
f02layers<-paste0('<g id="clima-layers">',paste0('<image data-category="clima-',seq_along(labs_c),'" href="',vapply(seq_along(labs_c),function(i)inline_raster(climate,paste0('clima-',i),i),''),'" width="',W,'" height="',H,'" pointer-events="none"/>',collapse=''),'</g><g id="suelo-layers" class="hidden">',paste0('<image data-category="suelo-',seq_along(labs_s),'" href="',vapply(seq_along(labs_s),function(i)inline_raster(soil,paste0('suelo-',i),i),''),'" width="',W,'" height="',H,'" pointer-events="none"/>',collapse=''),'</g>')
f02body<-paste0('<p class="muted">INEGI · clima: edición 2008, estaciones de 1921–1975 con cobertura heterogénea · suelo: observaciones 2002–2006, edición 2024.</p><p>Las categorías pueden compararse en el mapa y en su tabla de correspondencias. Las entidades aportan una referencia de localización; al seleccionarlas se conserva la clasificación nacional, con sus periodos y escalas.</p><div class="toolbar"><button id="reset">Restablecer vista</button><button id="download" class="primary">Descargar tabla filtrada CSV</button><button id="download-page">Descargar página CSV</button></div><div class="selectors">',state_selector,'<section class="selector"><h2>Clasificación consultada</h2><fieldset class="layer-controls"><legend>Capa</legend><label><input type="radio" name="layer" value="clima" checked>Clima</label><label><input type="radio" name="layer" value="suelo">Suelos</label></fieldset><label for="classification-search">Buscar código o descripción</label><input id="classification-search" type="search" placeholder="Por ejemplo: GRAVOSA o cálido" autocomplete="off"><p class="muted">La búsqueda filtra las correspondencias de la tabla; las casillas siguientes controlan las categorías del mapa.</p></section></div><div id="selection-chips" class="chips" aria-label="Entidades seleccionadas"></div><section id="detail" class="detail" aria-live="polite"></section><fieldset><legend id="category-legend">Categorías visibles</legend><div id="category-options" class="category-list"></div></fieldset><div class="map-tools"><fieldset class="layer-controls"><legend>Seleccionar en el mapa</legend><label><input type="radio" name="interaction" value="estado" checked>Entidad</label><label><input type="radio" name="interaction" value="categoria">Categoría</label></fieldset><button id="all-categories">Mostrar todas las categorías</button></div><p id="map-instruction" class="keyboard-hint">Clic o toque sobre una entidad la añade a la comparación. Con teclado, use Tab y Enter o Espacio; las listas ofrecen la misma selección.</p><svg id="map" class="map" viewBox="0 0 ',W,' ',H,'" role="group" aria-label="Mapa seleccionable de clima y suelo">',f02layers,'<g id="states"></g></svg><p class="muted">Dibujo generalizado a 1.8 km y contornos del Marco Geoestadístico 2020. Los colores muestran categorías de sus fuentes; la selección estatal ayuda a situarlas y no produce superficies, promedios o aptitudes por entidad.</p><div class="pager"><button id="previous">Página anterior</button><span id="page-label" class="status"></span><button id="next">Página siguiente</button></div><div class="table-wrap"><table id="data-table"><caption id="table-caption"></caption><thead id="table-head"></thead><tbody id="table-body"></tbody></table></div><details><summary>Clasificación, fechas y fuentes</summary><p class="muted">Clima: escala 1:1 000 000; TIPO_N 11, 12, 21, 22, 31, 32, 42 y 70 conservan su grupo; 51–64 se reúnen en secos y semisecos, y 92 identifica agua. En suelos, escala 1:250 000, R corresponde a piedras y r a gravas y guijarros. N reúne registros sin fase al captarse o con una condición muy homogénea, según el diccionario del productor; se conserva como «Sin fase registrada». La discordancia R/GRAVOSA aparece como dato inconsistente. La aptitud de un terreno se evalúa para un uso y manejo definidos, con información local.</p><p class="muted">La tabla filtrada conserva las filas originales que corresponden a las categorías representadas; la paginación facilita consultarlas. La descarga de página contiene sus filas visibles y la descarga filtrada reúne todas las páginas del mismo filtro.</p><p class="source">Fuentes: <a href="https://www.inegi.org.mx/app/biblioteca/ficha.html?upc=702825267568">INEGI, Unidades climáticas</a> · <a href="https://www.inegi.org.mx/app/biblioteca/ficha.html?upc=794551131916">Edafología Serie II</a>. Consulta documental 5 de noviembre de 2026.</p></details>')
f02js<-r"---(
const selectedStates=new Set(),chosen={clima:new Set(D.capas.clima.categorias.map(c=>c.id)),suelo:new Set(D.capas.suelo.categorias.map(c=>c.id))};let layer='clima',pageIndex=0,lastCategory=null,interaction='estado';const pageSize=20;
const cells=Object.fromEntries(Object.entries(D.capas).map(([k,v])=>{const a=new Uint8Array(v.columnas*v.renglones);let at=0;v.runs.lengths.forEach((n,i)=>{a.fill(v.runs.values[i],at,at+n);at+=n});return[k,a]}));
function filtered(){const q=plain($('classification-search').value);return D.capas[layer].filas.filter(r=>chosen[layer].has(Number(r.grupo_id))&&Object.values(r).some(v=>plain(v).includes(q)))}
function changeState(id){toggle(selectedStates,id);render()}
function changeCategory(id){toggle(chosen[layer],Number(id));lastCategory=Number(id);pageIndex=0;render()}
function categories(){const el=$('category-options');el.replaceChildren();for(const cat of D.capas[layer].categorias){const l=document.createElement('label');l.className='option'+(lastCategory===cat.id?' active':'');const c=document.createElement('input');c.type='checkbox';c.value=cat.id;c.checked=chosen[layer].has(cat.id);c.addEventListener('change',()=>changeCategory(cat.id));const sw=document.createElement('span');sw.className='swatch';sw.style.background=cat.color;l.append(c,sw,document.createTextNode(cat.nombre));el.append(l)}}
function render(){const focus=captureFocus(),data=D.capas[layer],rows=filtered(),pages=Math.max(1,Math.ceil(rows.length/pageSize));pageIndex=Math.min(pageIndex,pages-1);const slice=rows.slice(pageIndex*pageSize,(pageIndex+1)*pageSize);stateOptions($('state-search').value,selectedStates,changeState);stateMap(selectedStates,changeState);categories();chips($('selection-chips'),D.estados.filter(s=>selectedStates.has(s.cve_ent)).map(s=>({id:s.cve_ent,name:s.nombre})),changeState);
$('clima-layers').classList.toggle('hidden',layer!=='clima');$('suelo-layers').classList.toggle('hidden',layer!=='suelo');document.querySelectorAll('[data-category]').forEach(im=>{const [key,id]=im.dataset.category.split('-');im.style.display=chosen[key].has(Number(id))?'':'none'});$('states').style.pointerEvents=interaction==='estado'?'auto':'none';document.querySelectorAll('[data-state]').forEach(p=>p.setAttribute('tabindex',interaction==='estado'?'0':'-1'));
const names=D.estados.filter(s=>selectedStates.has(s.cve_ent)).map(s=>s.nombre),active=data.categorias.filter(c=>chosen[layer].has(c.id)),cat=data.categorias.find(c=>c.id===lastCategory);$('detail').innerHTML='<p class="status">'+(layer==='clima'?'Clima histórico':'Fases superficiales del suelo')+' · '+active.length+' categorías visibles</p><p>'+(names.length?'Contexto territorial: '+esc(names.join(', '))+'.':'Contexto nacional. Puede añadir entidades sin cambiar la unidad de la clasificación.')+'</p>'+(cat?'<p><strong>'+esc(cat.nombre)+'</strong> · '+(chosen[layer].has(cat.id)?'visible en el mapa y en la tabla.':'oculta; su casilla permite recuperarla.')+'</p>':'')+'<p class="muted">'+(layer==='clima'?'Edición 2008; base histórica de estaciones 1921–1975.':'Observaciones 2002–2006; edición 2024. R, r y N conservan su significado original.')+' Las correspondencias de la tabla son nacionales.</p>';
$('table-caption').textContent='Correspondencias '+(layer==='clima'?'climáticas':'edafológicas')+' · '+rows.length+' filas filtradas · '+(names.length?'contexto: '+names.join(', '):'contexto nacional');$('table-head').innerHTML='<tr>'+data.campos.map(k=>'<th scope="col">'+esc(k)+'</th>').join('')+'</tr>';$('table-body').innerHTML=slice.map(r=>'<tr>'+data.campos.map(k=>'<td>'+esc(r[k])+'</td>').join('')+'</tr>').join('')||'<tr><td colspan="'+data.campos.length+'" class="empty">No hay filas con esta búsqueda y categorías. Restablecer recupera la clasificación representada.</td></tr>';$('page-label').textContent='Página '+(pageIndex+1)+' de '+pages+' · '+slice.length+' filas en esta página';$('previous').disabled=pageIndex===0;$('next').disabled=pageIndex>=pages-1;$('download').disabled=!rows.length;$('download-page').disabled=!slice.length;$('map-instruction').textContent=interaction==='estado'?'Clic o toque añade o quita una entidad. Con teclado, Tab y Enter o Espacio permiten seleccionarla; las listas ofrecen la misma operación.':'Clic o toque consulta la categoría del punto y la mantiene seleccionada. Las casillas permiten añadir categorías para compararlas con teclado o toque.';restoreFocus(focus);publishHeight()}
$('state-search').addEventListener('input',()=>stateOptions($('state-search').value,selectedStates,changeState));$('classification-search').addEventListener('input',()=>{pageIndex=0;render()});document.querySelectorAll('input[name=layer]').forEach(r=>r.addEventListener('change',()=>{layer=r.value;pageIndex=0;lastCategory=null;$('classification-search').value='';render()}));document.querySelectorAll('input[name=interaction]').forEach(r=>r.addEventListener('change',()=>{interaction=r.value;render()}));$('previous').addEventListener('click',()=>{pageIndex--;render()});$('next').addEventListener('click',()=>{pageIndex++;render()});$('all-categories').addEventListener('click',()=>{chosen[layer]=new Set(D.capas[layer].categorias.map(c=>c.id));lastCategory=null;pageIndex=0;render()});
$('map').addEventListener('click',e=>{if(interaction!=='categoria')return;const pt=$('map').createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;const p=pt.matrixTransform($('map').getScreenCTM().inverse()),d=D.capas[layer],x=Math.floor(p.x/D.width*d.columnas),y=Math.floor(p.y/D.height*d.renglones);if(x<0||y<0||x>=d.columnas||y>=d.renglones)return;const id=cells[layer][y*d.columnas+x];if(!id)return;chosen[layer]=new Set([id]);lastCategory=id;pageIndex=0;render()});
$('download').addEventListener('click',()=>csvDownload('F02-'+layer+'-clasificacion-nacional-filtrada.csv',D.capas[layer].campos,filtered()));$('download-page').addEventListener('click',()=>csvDownload('F02-'+layer+'-pagina-'+(pageIndex+1)+'.csv',D.capas[layer].campos,filtered().slice(pageIndex*pageSize,(pageIndex+1)*pageSize)));$('reset').addEventListener('click',()=>{selectedStates.clear();for(const k of ['clima','suelo'])chosen[k]=new Set(D.capas[k].categorias.map(c=>c.id));layer='clima';interaction='estado';lastCategory=null;pageIndex=0;$('state-search').value='';$('classification-search').value='';document.querySelector('input[name=layer][value=clima]').checked=true;document.querySelector('input[name=interaction][value=estado]').checked=true;render()});window.figureState=()=>({estados:[...selectedStates],capa:layer,categorias:[...chosen[layer]],filas:filtered(),pagina:pageIndex,filasPagina:filtered().slice(pageIndex*pageSize,(pageIndex+1)*pageSize)});render();
)---"
page('F02-clima-suelos.html','Condiciones climáticas y características superficiales del suelo',f02body,list(estados=state_data,width=unname(W),height=unname(H),capas=list(clima=layer_data(climate,labs_c,col_c,climate_rows,names(climate_rows)),suelo=layer_data(soil,labs_s,col_s,soil_rows,names(soil_rows)))),f02js)
cat('F02: explorador HTML generado, categorías y correspondencias nacionales conservadas.\n')
